import type { ParagraphSpec } from '../paragraph-spec.ts';

export type ParagraphKey = string;

export function createParagraphLayoutKey(spec: ParagraphSpec): ParagraphKey {
  const {
    ranges: _ranges,
    ...layoutSpec
  } = spec;

  return JSON.stringify(layoutSpec);
}

export function createParagraphKey(spec: ParagraphSpec): ParagraphKey {
  return createParagraphLayoutKey(spec);
}

/**
 * Full-identity cache key (layout fields + ranges), reusing an already
 * computed layout key instead of re-stringifying the whole spec. Backends
 * previously computed `JSON.stringify(spec)` from scratch for this on every
 * `prepare()` call (including cache hits), redundantly re-serializing every
 * field `createParagraphLayoutKey` had already serialized.
 */
export function createFullParagraphKey(spec: ParagraphSpec, layoutKey: ParagraphKey): ParagraphKey {
  if (!spec.ranges || spec.ranges.length === 0) {
    return layoutKey;
  }
  return `${layoutKey}|ranges:${JSON.stringify(spec.ranges)}`;
}
