/** Canonical unit for every paragraph-local offset in `@exact/text`. */
export const PARAGRAPH_OFFSET_UNIT = 'utf16-code-unit' as const;

export type ParagraphOffsetUnit = typeof PARAGRAPH_OFFSET_UNIT;

declare const utf16OffsetBrand: unique symbol;

/**
 * A paragraph-local UTF-16 code-unit offset.
 *
 * The optional flavor keeps ordinary numeric arithmetic ergonomic inside the
 * incubating API while preserving the unit in declarations and editor hints.
 */
export type Utf16Offset = number & {
  readonly [utf16OffsetBrand]?: ParagraphOffsetUnit;
};

export interface Utf16Range {
  readonly start: Utf16Offset;
  readonly end: Utf16Offset;
}

export function asUtf16Offset(value: number): Utf16Offset {
  return value as Utf16Offset;
}
