/**
 * A minimal LRU-bounded Map. `get` promotes the entry to most-recently-used
 * (by re-inserting it, which moves it to the end of Map iteration order);
 * `set` evicts the least-recently-used entry (the first key in iteration
 * order) once `maxEntries` would be exceeded.
 *
 * Used to cap the prepared-paragraph / paragraph-layout caches in the text
 * geometry backends (`pretext-backend.ts`, `apple-backend.ts`), which are
 * held by module-level singletons and previously grew without bound for the
 * app's lifetime — every distinct paragraph spec added an entry that was
 * never freed.
 */
export class BoundedLruMap<K, V> {
  private readonly map = new Map<K, V>();

  constructor(private readonly maxEntries: number) {}

  get size(): number {
    return this.map.size;
  }

  get(key: K): V | undefined {
    const value = this.map.get(key);
    if (value === undefined) {
      return undefined;
    }
    // Promote to most-recently-used.
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  set(key: K, value: V): void {
    if (this.map.has(key)) {
      this.map.delete(key);
    } else if (this.map.size >= this.maxEntries) {
      const oldestKey = this.map.keys().next().value as K | undefined;
      if (oldestKey !== undefined) {
        this.map.delete(oldestKey);
      }
    }
    this.map.set(key, value);
  }

  clear(): void {
    this.map.clear();
  }
}
