import type { ParagraphRangeAnnotation, ParagraphSpec } from './paragraph-spec.ts';
import {
  PARAGRAPH_OFFSET_UNIT,
  type ParagraphOffsetUnit,
  type Utf16Offset,
  type Utf16Range,
} from './text-position.ts';

declare const paragraphHandleBrand: unique symbol;
declare const lineCursorBrand: unique symbol;

export type ParagraphHandle = {
  readonly [paragraphHandleBrand]: true;
};

export type LineCursor = {
  readonly [lineCursorBrand]: true;
};

export interface Point {
  readonly x: number;
  readonly y: number;
}

export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** @deprecated Prefer the unit-explicit `Utf16Range` name. */
export type TextRange = Utf16Range;

export type GeometryAccuracy = 'exact-clusters' | 'approximate';

/** RFC 0095 OQ1: this API may still make accuracy/unit-breaking changes. */
export const TEXT_GEOMETRY_API_STABILITY = 'incubator' as const;

export type TextGeometryFeatureSupport =
  | 'supported'
  | 'unsupported'
  | 'default-only'
  | 'single-value'
  | 'geometry-neutral';

export type TextGeometryQuerySupport =
  | 'supported'
  | 'per-line'
  | 'single-width'
  | GeometryAccuracy;

// @system @ref LLP 0095: one descriptor makes backend feature support,
// position units, and shaped-geometry accuracy inspectable before a query.
export interface TextGeometryBackendCapabilities {
  readonly apiStability: typeof TEXT_GEOMETRY_API_STABILITY;
  readonly backendId: string;
  readonly offsetUnit: ParagraphOffsetUnit;
  readonly geometryAccuracy: GeometryAccuracy;
  readonly attachments: {
    readonly support: 'supported' | 'unsupported';
    readonly canonicalOffsetCharacter: 'U+FFFC';
    readonly canonicalUtf16CodeUnits: 1;
  };
  readonly paragraphSpec: {
    readonly textSpans: TextGeometryFeatureSupport;
    readonly rangeAnnotations: TextGeometryFeatureSupport;
    readonly locale: TextGeometryFeatureSupport;
    readonly baseDirection: TextGeometryFeatureSupport;
    readonly writingMode: TextGeometryFeatureSupport;
    readonly textAlign: TextGeometryFeatureSupport;
    readonly lineBreak: TextGeometryFeatureSupport;
    readonly overflowWrap: TextGeometryFeatureSupport;
    readonly maxLines: TextGeometryFeatureSupport;
    readonly truncation: TextGeometryFeatureSupport;
  };
  readonly textStyle: {
    readonly color: TextGeometryFeatureSupport;
    readonly fontFamily: TextGeometryFeatureSupport;
    readonly fontSize: TextGeometryFeatureSupport;
    readonly fontWeight: TextGeometryFeatureSupport;
    readonly fontStyle: TextGeometryFeatureSupport;
    readonly fontVariantNumeric: TextGeometryFeatureSupport;
    readonly fontFeatureSettings: TextGeometryFeatureSupport;
    readonly fontVariationSettings: TextGeometryFeatureSupport;
    readonly textAlign: TextGeometryFeatureSupport;
    readonly writingMode: TextGeometryFeatureSupport;
    readonly lineHeight: TextGeometryFeatureSupport;
    readonly letterSpacing: TextGeometryFeatureSupport;
    readonly textDecorationLine: TextGeometryFeatureSupport;
    readonly locale: TextGeometryFeatureSupport;
  };
  readonly queries: {
    readonly measure: TextGeometryQuerySupport;
    readonly minContentWidth: TextGeometryQuerySupport;
    readonly maxContentWidth: TextGeometryQuerySupport;
    readonly layoutLines: TextGeometryQuerySupport;
    readonly nextLine: TextGeometryQuerySupport;
    readonly layoutWithLineWidths: TextGeometryQuerySupport;
    readonly rangeRects: TextGeometryQuerySupport;
    readonly rangeAnnotationsAt: TextGeometryQuerySupport;
    readonly hitTest: TextGeometryQuerySupport;
  };
}

export interface GeometryResultMetadata {
  readonly geometryAccuracy: GeometryAccuracy;
  readonly offsetUnit: ParagraphOffsetUnit;
}

export function assertExactClusterGeometry(
  value: Pick<GeometryResultMetadata, 'geometryAccuracy'>,
  consumer: string,
): void {
  if (value.geometryAccuracy !== 'exact-clusters') {
    throw new Error(
      `${consumer} requires exact-clusters text geometry; received ${value.geometryAccuracy}.`,
    );
  }
}

export interface ParagraphMetrics extends GeometryResultMetadata {
  readonly width: number;
  readonly height: number;
  readonly lineCount: number;
  readonly didTruncate: boolean;
}

export interface ParagraphLine extends GeometryResultMetadata {
  readonly index: number;
  readonly textRange: TextRange;
  readonly width: number;
  readonly height: number;
  readonly baseline: number;
  readonly origin: Point;
}

export interface ParagraphLineStep {
  readonly line: ParagraphLine;
  readonly cursor: LineCursor;
}

export interface ParagraphRangeRect extends GeometryResultMetadata {
  readonly lineIndex: number;
  readonly rect: Rect;
}

export interface ParagraphHitTestResult extends GeometryResultMetadata {
  readonly offset: Utf16Offset;
  readonly affinity: 'forward' | 'backward';
  readonly isInside: boolean;
  readonly activeAnnotations: readonly ParagraphRangeAnnotation[];
}

export interface ParagraphMeasureOptions {
  readonly maxWidth: number;
}

export interface ParagraphLayoutOptions {
  readonly maxWidth: number;
}

export type ParagraphLineWidthResolver = (y: number) => number;

export interface PreparedParagraph extends GeometryResultMetadata {
  readonly handle: ParagraphHandle;
  readonly spec: ParagraphSpec;
  readonly capabilities: TextGeometryBackendCapabilities;
  measure(options: ParagraphMeasureOptions): ParagraphMetrics;
  minContentWidth(): number;
  maxContentWidth(): number;
  layoutLines(options: ParagraphLayoutOptions): readonly ParagraphLine[];
  nextLine(cursor: LineCursor | null, options: ParagraphLayoutOptions): ParagraphLineStep | null;
  layoutWithLineWidths(getWidthForLineY: ParagraphLineWidthResolver): readonly ParagraphLine[];
  rangeRects(range: TextRange, options: ParagraphLayoutOptions): readonly ParagraphRangeRect[];
  rangeAnnotationsAt(position: Utf16Offset): readonly ParagraphRangeAnnotation[];
  hitTest(point: Point, options: ParagraphLayoutOptions): ParagraphHitTestResult | null;
}

export interface TextGeometryBackend {
  readonly capabilities: TextGeometryBackendCapabilities;
  readonly geometryAccuracy: GeometryAccuracy;
  readonly offsetUnit: ParagraphOffsetUnit;
  prepare(spec: ParagraphSpec): PreparedParagraph | Promise<PreparedParagraph>;
  clearCache?(): void;
}

export interface SyncTextGeometryBackend extends TextGeometryBackend {
  prepare(spec: ParagraphSpec): PreparedParagraph;
}

export { PARAGRAPH_OFFSET_UNIT };
export type { ParagraphOffsetUnit, Utf16Offset, Utf16Range };
